// Status-screen animation (48 x 40 px box at x=108, y=18), see docs/13_display_animation_briefing.md.
// Artwork: mascot LIO, anim/manifest.json (accent colour per state).
//
// The frames live in anim_data.inc, generated by tools/make_anim.py from the PNG film strips in
// main/anim/. This module only decides WHICH frame is due and copies it into the display
// framebuffer; the caller (ui.c) flushes. Nothing here allocates; all calls come from the UI task.
#pragma once

#include <stdbool.h>
#include <stdint.h>

#define ANIM_X 108
#define ANIM_Y 18
#define ANIM_W 48
#define ANIM_H 40

// Numbers = the file numbers of the LIO sprite sheets (anim/NN_name_spritesheet_*.png).
typedef enum {
    ANIM_NONE = 0,
    ANIM_READY = 1,        // ready for upload (owner APP) or drive provided to the host and idle
    ANIM_UPLOAD = 2,       // web upload running
    ANIM_DOWNLOAD = 3,     // USB host reads or writes
    ANIM_PROCESSING = 4,   // long task: copy, format, update (anim_set_busy)
    ANIM_SUCCESS = 5,      // plays once after LOCKED -> UNLOCKED
    ANIM_CONNECTING = 6,   // Wi-Fi connecting / setup access point
    ANIM_DISCONNECTED = 7, // no Wi-Fi configured, no access point
    ANIM_LOCKED = 8,       // encrypted and locked
    ANIM_ERROR = 9,        // error
    ANIM_COUNT = 10
} anim_id_t;

/** Select the animation; restarts it from frame 0 only if it differs from the current one. */
void anim_set(anim_id_t id, int64_t now_ms);

/** Advance by time. true = the frame to show differs from the one last drawn (redraw the box). */
bool anim_tick(int64_t now_ms);

/** Copy the current frame into the framebuffer (box only, no flush). Marks it as drawn. */
void anim_draw(void);

/** true once a non-looping animation has shown its last frame for one frame time. */
bool anim_finished(int64_t now_ms);

/** true if an animation with frames exists for this id (the box is then reserved). */
bool anim_available(anim_id_t id);

/** For code that runs long tasks (copy, format, update): while set, the status screen shows ANIM_PROCESSING. */
void anim_set_busy(bool busy);
bool anim_is_busy(void);
